import{_ as o,o as l,c as r,ag as p}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"03.11 精华题与补充题","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/91-精华题与补充题.md","filePath":"03-软件工程基础/91-精华题与补充题.md"}'),i={name:"03-软件工程基础/91-精华题与补充题.md"};function e(s,t,a,n,_,g){return l(),r("div",null,[...t[0]||(t[0]=[p('<h1 id="_03-11-精华题与补充题" tabindex="-1">03.11 精华题与补充题 <a class="header-anchor" href="#_03-11-精华题与补充题" aria-label="Permalink to &quot;03.11 精华题与补充题&quot;">​</a></h1><ol><li><p>【模型识别】为下列项目选模型：① 需求明确的银行核心系统改造；② 需求模糊的管理信息系统；③ 高风险的大型航天控制软件；④ 需求多变的互联网创业产品。</p></li><li><p>【内聚耦合】写出下列模块的内聚类型：① 一个模块按参数值分别执行存文件或打印操作（功能无关、逻辑相似）；② 一个模块对同一批学生成绩数据先统计平均分、再排序、再打印报表；③ 一个模块把三个互不相关的函数凑在一起，只因为写代码时顺手。</p></li><li><p>【内聚耦合】区分耦合类型：① 模块间传递一个开关量标志决定对方执行哪个分支；② 模块间传递一个整数；③ 模块间传递整个&quot;职工记录&quot;结构；④ 两个模块都直接修改同一全局变量 count。</p></li><li><p>【McCabe】某程序流程图包含 4 个判定节点，其控制流图有 12 条边、9 个节点。用两种方法求 V(G) 并互相验证。</p></li><li><p>【逻辑覆盖】对语句 <code>if (A&gt;0 AND B&gt;0) s=1; else s=0;</code>：用例 T1(A=1,B=0)、T2(A=0,B=1) 满足了哪种覆盖？没满足哪种覆盖？</p></li><li><p>【维护分类】指出维护类型：① 修改程序中一处导致统计错误的计算 bug；② 为两年后的系统改造提前重构核心模块；③ 用户要求增加微信通知功能；④ 数据库从 Oracle 迁移到 PostgreSQL。</p></li><li><p>【CMM】&quot;组织对软件过程和产品质量建立了定量的度量与控制&quot;→ 第几级？</p></li></ol><hr><h2 id="补充题-模块设计原则-测试计算-项目管理-dfd-专项" tabindex="-1">补充题（模块设计原则 / 测试计算 / 项目管理 / DFD 专项） <a class="header-anchor" href="#补充题-模块设计原则-测试计算-项目管理-dfd-专项" aria-label="Permalink to &quot;补充题（模块设计原则 / 测试计算 / 项目管理 / DFD 专项）&quot;">​</a></h2><blockquote><p>这四块是真题的密集出题区：<strong>模块设计六原则</strong>（第三节 3.1）、<strong>由流程图数用例数与 McCabe</strong>（4.8 / 4.9）、<strong>沟通路径与甘特/PERT</strong>（7.1 / 7.2）、<strong>DFD 的补实体 / 补存储 / 补加工名与三种错误</strong>（9.4–9.7）。</p></blockquote><p><strong>一、选择题</strong></p><ol><li><p>关于模块设计原则，下列说法<strong>错误</strong>的是（ ）。 A. 模块的扇入指该模块直接上级模块的个数 B. 模块的作用域应当包含在该模块的控制域之内 C. 模块的规模越小越好，拆得越细就越容易维护 D. 深度过大说明有些模块设计得过于简单，应当考虑合并</p></li><li><p>某程序的控制流图为：语句 S1 之后是判定 A（A 的真分支执行 S2，假分支进入判定 B）；判定 B 的真分支执行 S3、假分支执行 S4；S2、S3、S4 执行完毕后都汇合到 S5 结束。该程序的 McCabe 环路复杂度是（ ）。 A. 2 B. 3 C. 4 D. 8</p></li><li><p>某项目组共 6 人，不设主程序员，成员之间需要直接沟通，则沟通路径数为（ ）。 A. 6 B. 15 C. 30 D. 36</p></li><li><p>关于甘特图与 PERT 图，下列说法<strong>正确</strong>的是（ ）。 A. 甘特图能清晰反映各任务之间的依赖关系 B. PERT 图不能反映任务之间的并行关系，但能清晰反映任务之间的依赖关系 C. 甘特图能反映依赖关系，PERT 图能反映并行关系 D. 两者都只能反映任务从何时开始到何时结束，其余都不能反映</p></li><li><p>某 0 层图中一个加工只画出了进入它的数据流，没有任何从它流出的数据流。该图违反了 DFD 的平衡原则，这种错误称为（ ）。 A. 黑洞 B. 奇迹 C. 灰洞 D. 黑盒</p></li></ol><p><strong>二、案例题（数据流图：补外部实体、补数据存储、判断加工错误）</strong></p><p>阅读下列说明，回答问题 1 至问题 3。</p><p>【说明】某图书馆管理系统的图书借还与状态维护业务如下：</p><ol><li>读者向系统提交借书申请（含读者证号、图书条码）。</li><li>系统根据读者证号，从读者文件中读取该读者的借阅资格与已借数量，进行借阅资格校验。</li><li>校验通过后，系统从图书文件中读取该图书的在馆状态；将借阅记录写入借阅文件，同时向读者发送借阅成功通知。</li><li>图书管理员向系统提交还书请求（含图书条码），系统将图书文件的在馆状态更新为&quot;在馆&quot;，并向管理员返回还书结果。</li></ol><p>Top 层图外部实体与 0 层图一致。0 层图已画出四个加工：①处理借书申请、②校验借阅资格、③生成借阅记录、④处理还书；并画出了这些数据流：读者→①（借书申请）、①→②（读者证号）、②→③（校验结果）、①→读者（借阅成功通知）、管理员→④（还书请求）、④→管理员（还书结果）。</p><p><strong>问题 1</strong>：指出该系统的外部实体有哪些。</p><p><strong>问题 2</strong>：该系统需要哪些数据存储（文件）？并指出其中哪些文件被加工④读写。</p><p><strong>问题 3</strong>：图中加工④&quot;处理还书&quot;只有&quot;管理员→④（还书请求）&quot;这条输入流和&quot;④→管理员（还书结果）&quot;这条输出流，没有任何与数据存储相连的流。请指出这属于 DFD 的哪种错误，说明理由，并给出正确的补法。</p><hr>',16)])])}const d=o(i,[["render",e]]);export{u as __pageData,d as default};
